public async Task HandleAsync(BillingEvent msg, CancellationToken ct)
{
    await using var tx = await _db.Database.BeginTransactionAsync(ct);

    // 1) Dedup as part of the SAME transaction as the business write.
    //    Unique index on MessageId makes the race impossible to lose.
    var inserted = await _db.Database.ExecuteSqlAsync($"""
        INSERT INTO ProcessedMessages (MessageId, ProcessedAt)
        VALUES ({msg.MessageId}, {DateTime.UtcNow})
        ON CONFLICT (MessageId) DO NOTHING
        """, ct) == 1;

    if (!inserted)
    {
        await tx.CommitAsync(ct);      // duplicate: ack it, change nothing
        _log.LogInformation("Duplicate {MessageId} skipped", msg.MessageId);
        return;
    }

    // 2) Business effect — visible only once, committed with the dedup record.
    _db.Invoices.Add(Invoice.From(msg));
    await _db.SaveChangesAsync(ct);
    await tx.CommitAsync(ct);          // ack the message only AFTER commit
}

// Schema:
// CREATE TABLE ProcessedMessages (
//     MessageId  uniqueidentifier PRIMARY KEY,
//     ProcessedAt timestamp NOT NULL
// );

// Ordering caveat: dedup fixes duplicates, not reordering.
// If order matters, include a monotonic sequence per aggregate and
// reject/stash out-of-sequence messages (or use partitioned,
// key-based ordering — one aggregate id always lands on one partition).
